internal object DuaSaDraft6 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_rahmataka_arju" to DuaText("भवतः दयायाः अहं आशा करोति।", "हे अल्लाहः, भवतः दयायाः एव अहं आशां करोति, अतः मम नेत्रक्षरणकालपर्यन्तं न वदतु, मम सर्वकार्याणि च सम्यक् करोतु। त्वं विहाय अन्यत् ईश्वरः नास्ति।", "दुःखग्रस्तस्य दुआ (दावत् अल्-मक्रब्)।", "सः पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् इत्यनेन सङ्कटे तस्य दुआ इति नाम्ना अभिनिहितः।"),
        "dua_against_enemy_ahzab" to DuaText("शत्रु सेना विरुद्धम्", "हे अल्लाहः, ग्रन्थस्य प्रकाशकः, शीघ्रं गणनं करोतु। सङ्घान् पराजयताम्। हे अल्लाहः, तान् पराजय्य, तान् उल्लङ्घय।", "शत्रोः विरुद्धं-सङ्घस्य युद्धस्य दुआ।", "सः शत्रु-विरुद्धं पैगम्बरस्य सल्लल्लाहु अलैहि वसल्लम्-दुआ।"),
        "dua_anta_adudi" to DuaText("त्वं मम समर्थकः।", "हे अल्लाहः, त्वं मम सहायकः सहायकः च अस्मि। अहं भवतः द्वारा योजना करोति, भवतः द्वारा अहं अग्रे गच्छामि, भवतः द्वारा अहं युद्धं करोमि।", "स्पर्धायाः पूर्वम् अथवा प्रमुखे चुनौतीः।", "सः पैगम्बरः (सः) युद्धे इदं उक्तवान्।"),
        "dua_ikfinihim" to DuaText("तेषां विरुद्धं मह्यं पर्याप्तं करोतु।", "हे अल्लाहः, तेषां विरुद्धं भवतः इच्छानुसारं मह्यं पर्याप्तं करोतु।", "उत्पीडकेभ्यः दुष्टतायाः विरुद्धं-द पीपल् आफ् द डिच् इति कथायां बालस्य दुआ।", "अल्लाहः बालकं उत्पीडकात् रक्षितवान्।"),
        "dua_qadarullah" to DuaText("यदा किमपि अशुभं भवति।", "अयं अल्लाहस्य आदेशः अस्ति, सः स्वस्य इच्छानुसारं कार्यं कृतवान्।", "यदा किमपि अप्रियं भवति, तदा'यदि केवलं'इति वदति।", "'यदि केवलं'शैतानस्य द्वारं उद्घाटयति।"),
        "dua_ala_kulli_hal" to DuaText("प्रत्येकं परिस्थितौ प्रशंसाम्।", "प्रत्येकं परिस्थितौ सर्वस्य प्रशंसा अल्लाहस्य एव भवति।", "यदा किमपि अप्रियं भवति।", "सः पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् इत्यनेन स्वस्य अप्रीतिकरस्य विषये उक्तवान्।"),
        "dua_dogs_barking" to DuaText("रात्रौ शुन्य कुत्राः भुम्माः।", "शप्तात् शयतान् इत्यतः अहं अल्लाहस्य शरणं प्रार्थये।", "शुन्य रात्रौ शावकाः भुम्मा वा गधः वा ब्राये।", "भवान् यत् न पश्यति तत् ते पश्यन्ति।"),
        "dua_leaving_home_adilla" to DuaText("भ्रमात् शरणम्", "हे अल्लाहः, अहं तव शरणं याचामि, येन अहं भ्रमे वा भ्रमे वा न गच्छामि, येन अहं भ्रमे वा न गच्छामि, अन्यथा अहं भ्रमे वा अन्यायः वा न भवामि, अन्यथा अहं मूर्खतापूर्णं वा आचरामि वा मूर्खतापूर्णं वा आचरामि।", "गृहात् निर्गमने-उम्-सलमा (रा.) इत्यनेन कथितं।", "यदा यदा सः स्वगृहात् निर्गच्छति तदा सः पैगम्बरः (स) इदं पठति स्म।"),
        "dua_ascending_descending" to DuaText("ऊर्ध्वगमनं च अधः आगमनम्", "अल्लाहः सर्वात् महान् अस्ति (यदा ऊर्ध्वगमनं भवति)।-- अल्लाहः महिमितः।", "यात्रायां, ऊर्ध्वगमनसमये'अल्लाहु अक्बर्'इति, अधः अवतरणकाले'सुभानल्लाह्'इति च वदतु।", "यात्रायां सहचरानां (आर्. ए.) अभ्यासः।"),
        "dua_traveller_sahar" to DuaText("प्रातःकालात् पूर्वं यात्रिकस्य दुआ", "एकः श्रोता अल्लाहस्य प्रशंसां, तस्य कृपेः च अस्माभिः विषये श्रुतवान्। हे अस्माकं प्रभुः, अस्माभिः सह गत्वा अस्माभिः आश्रयं प्रार्थयतां, अस्माभिः सह युष्मपि अनुग्रहं करोतु।", "यात्रायां, प्रातःकाले।", "पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् इत्येषः यात्रायाः समये प्रातःकाले एव एतत् उक्तवान्।"),
        "dua_zawwadakallah" to DuaText("यात्रिकाय अल्लाहः तक्वा प्रदातुं शक्नोति।", "अल्लाहः भवतः यात्रायाः कृते तक्वा प्रदातुं शक्नोति, भवतः पापान् क्षमिष्यति, यत्र च भवन्तः भवतां कृते सौख्यम् कल्पयतु।", "यदा यात्रिकाय विदयः भवति।", "पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् इत्येषः यात्रां निर्मायिताय कस्मिंश्चित् इदं दुआ दत्तवान्।"),
        "dua_traveller_to_resident" to DuaText("पश्चस्थानां कृते यात्रिकः", "अहं तव ईश्वरं समर्पयेते, यस्य विश्वासः कदापि न नष्टः भवति।", "परिवारेण विदायां स्वीकृत्य यात्रिकः उक्तवान्।", "परिवारस्य सुरक्षां अल्लाहाय समर्पयतु।"),
        "dua_entering_village" to DuaText("नगरे वा ग्रामे वा प्रविशति।", "हे अल्लाहः सप्त आकाशाणां सर्वानां च छायानां च स्वामी, सप्त पृथिव्याः सर्वानां च स्वामी, भूतानानां सर्वानां च स्वामी, भूतानानां सर्वानां च स्वामी, वायु-सर्वानां च स्वामी, ते सर्वानां च पथभ्रष्टान्, वायु-सर्वानां च स्वामी! वयं भवतः कृते अस्य नगरस्य कल्याणार्थं, तस्य जनानां कल्याणार्थं च प्रार्थयामः, तस्य अशुभात्, तस्य जनानां अशुभात्, तस्य दुष्टात् च भवतः शरणं प्रार्थयामः।", "नगरं वा नगरं वा प्रवेष्टुं पूर्वं।", "यदा यदा सः कस्मैचित् नगरे प्रवेष्टुम् इच्छति तदा सः पैगम्बरः (सल्लल्लाहु अलैहि वसल्लम्) एतत् पठति स्म।"),
        "dua_vehicle_stumbles" to DuaText("यदा वाहनं पतति", "अल्लाहस्य नाम्नम्।", "यदा आरोहणं वा वाहनं वा पतति अथवा पतति,'शैतान् नाशः भवेत्'इति वदितुं न।", "बिस्मिल्ला इति वदन् शैतान्-नामकं मक्खिपर्यन्तं सङ्कोचयति।"),
        "dua_ajz_kasal_haram" to DuaText("दुर्बलता तथा वृद्धावस्थायाः शरणम्", "हे अल्लाहः, अहं निस्सहायतायाः अलसतायाः च, कायरता वृद्धावस्थायाः च, जीवनस्य मृत्योः च परीक्षायाः, समाध्याः दण्डस्य च शरणं प्रार्थये।", "आश्रयस्य समग्रः दैनिकः दुआ।", "सः प्रायः पैगम्बरस्य दूतः।"),
        "dua_sharri_ma_amiltu" to DuaText("मम दुष्कृत्यात् शरणम्।", "हे अल्लाहः, अहं यत् कर्म्मम् अकरोत् तस्य दुष्टात्, अहं यत् न कृतवान् तस्य दुष्टात् च शरणं प्रार्थये।", "आयशा (रा.) इत्यस्य मतेन, पैगम्बरस्य दुआ।", "यत् कृतम्, यत् पूर्ववत् अवशिष्टम् इति उभयोः परिणामात् रक्षणं।"),
        "dua_jahdil_bala" to DuaText("गम्भीरपरीक्षाः शरणार्थिनः।", "हे अल्लाहः, अहं कठिनपरीक्षातः, दुर्दशया, दुष्टशासनात्, शत्रूनां उल्लासात् च भवतः शरणं प्रार्थये।", "कठिनपरीक्षाभिः, शत्रूनां उल्लासात् च शरणम्।", "पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् एभ्यः चतुर्णां वस्तूनां शरणं प्राप्तवान्।"),
        "dua_fitnat_ghina_faqr" to DuaText("धनस्य दारिद्र्यस्य च परीक्षणात् शरणम्", "हे अल्लाहः, अहं आलस्यात् वृद्धावस्थात्, पापात् ऋणात्, समाधि-परीक्षणात्, अग्नि-परीक्षणात्, अग्नि-परीक्षणात्, धनस्य परीक्षणस्य दुष्टतायाः, दारिद्र्यस्य परीक्षणात् च शरणं प्रार्थये।", "समाधिः, नरकः, धनम्, दारिद्र्यं (दुआ इत्यस्य भागः) इत्येतयोः परीक्षणात् शरणम्।", "पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् इत्यतः शरणार्थं विस्तृतः द्वयः।"),
        "dua_kufr_faqr" to DuaText("अविश्वासः दारिद्र्यम् च शरणम्।", "हे अल्लाहः, अहं अविश्वासात् दारिद्र्यात् च भवतः शरणं याचामि, तथा च समाधिशिक्षातः भवतः शरणं याचामि। भवतः विना अन्यः देवः नास्ति।", "प्रातः सायं च त्रिवारं।", "अबू बक्राह् (र.) इत्ययं पैगम्बरं इदं वदन् श्रुतवान्।"),
        "dua_sharri_sami" to DuaText("मम इन्द्रियानां दुष्टतायाः शरणम्।", "हे ईश्वरः, मम श्रवणस्य दुष्टात्, मम दृष्टेः दुष्टात्, मम भाषायाः दुष्टात्, मम हृदयस्य दुष्टात्, मम इच्छायाः दुष्टात् च अहं भवतः शरणं प्रार्थये।", "शकल् इब्न् हुमायद् (र. अ.) इत्यस्मै शिक्षितः।", "अङ्गान् आत्मान् च पापात् रक्षयितुं दुआ।"),
        "dua_hadm_gharaq" to DuaText("आकस्मिकमरणात् दुर्घटनाभ्यः च शरणम्", "हे अल्लाहः, अहं भवतः आश्रयं प्रार्थयेम्, (भवनेन) क्षिप्तात्, ऊर्ध्वतः पतनात्, निमज्जनात्, ज्वालयात्, वृद्धावस्थया च, मृत्योः समये मम मार्गम् अपभ्रष्टं कर्तुं, भवतः मार्गात् पलायनं कुर्वन् म्रियितुं, (विषाक्तः) दंशनम्।", "दुर्घटनाभ्यः, दुर्मरणं च शरणम्।", "सः पैगम्बरस्य शरणार्थि अस्ति।"),
        "dua_ju_khiyanah" to DuaText("क्षुधा तथा विश्वासघातः इति शरणम्", "हे अल्लाहः, अहं क्षुधा-निवारणं युष्मभ्यन्तरे शरणं याचामि, यतः सः दुष्टः सहचरः अस्ति, विश्वासघातात् शरणं याचामि, यतः सः दुष्टः विश्वासपात्रः अस्ति।", "क्षुधा विश्वासघातः च शरणम्।", "सः पैगम्बरस्य शरणार्थि अस्ति।"),
        "dua_huda_tuqa" to DuaText("मार्गदर्शनं, भक्तिः, पवित्रता, पर्याप्तता च", "हे अल्लाह, अहं भवतः मार्गदर्शनं, भक्तिः, पवित्रता, आत्मनिर्भरता च प्रार्थये।", "पैगम्बरस्य संक्षिप्तं, विस्तृतं दुआ।", "धर्मस्य तथा अस्य विश्वस्य च चतुर्णां मूल-आशीर्वादानां।"),
        "dua_aslih_li_dini" to DuaText("मम धर्मस्य, जगतः, परकाले च परिष्करतु।", "हे अल्लाहः, मम धर्मस्य सम्यक् स्थापय, यः मम सर्वकाराणां रक्षाकरः अस्ति, मम लौकिकजीवनं सम्यक् स्थापय, यस्मिन् मम जीविका अस्ति, मम परकाले च सम्यक् स्थापय, यस्मात् अहं प्रत्यागमामि। मम कृते जीवनं सर्वसुधारणे वर्धयन्तु, मृत्युं सर्वसु दुष्टात् निवारयन्तु।", "धर्मस्य, विश्वस्य, परकाले च-तिस्रौ च संस्कारः।", "पैगम्बरस्य विस्तृतः दुआ।"),
        "dua_musarrifal_qulub" to DuaText("भवतः आज्ञापालनार्थं अस्माकं हृदयम् परिवृत्तव्यम्।", "हे अल्लाहः, हृदय-परिवर्तकः, भवतः आज्ञापालनार्थं अस्माकं हृदयम् परिवर्तयतु।", "आज्ञापालनस्य कृते हृदयस्य दृढतां साधयितुं दुआ।", "सर्वानां जनानाम् हृदयानि परम करुणामयस्य अङ्गुलिद्वयम् मध्ये सन्ति।"),
        "dua_jannah_nar" to DuaText("जन्नाम्, अग्निः शरणम् इति प्रार्थयतां।", "हे अल्लाहः, अहं तव स्वर्गं याचामि, अग्निः भवतः शरणं च प्रार्थयामि।", "ताशाहहुद् इत्यस्य अनन्तरं अथवा कस्यापि समये।", "पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् अवदत्-अस्माकं दुआः अपि एतं परितः एव परिभ्रमन्ति।"),
        "dua_khayri_kullih" to DuaText("सर्वम् उत्तमम्, इदानीं तथा पश्चात्", "हे अल्लाहः, अहं भवतः कृते सर्वं उत्तमं प्रार्थयेते-तत्क्षणात् विलम्बितं, तत्क्षणात् विलम्बितं, तत्क्षणात् विलम्बितं, तत्क्षणात् विलम्बितं, तत्क्षणात् अहं जानामि, तत्क्षणात् अहं न जानामि इति सर्वात् दुष्टात् अहं शरणं याचयेते। हे अल्लाहः, अहं भवतः कृते स्वर्गं याचयेते, तथा च यः कश्चित् शब्दः कर्म्माणि तत् समीपीकरोति, अहं अग्निः, तथा च यः कश्चित् वचनानि कर्माणि तत् समीपीकरोति, तेन शरणं याचयेते।", "पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् इत्येषः आयशा (रा) (दुआ इत्यस्य भागः) इत्यस्मै अयं व्यापकः दुआ उपदिशत्।", "यः दुआ सर्वान् सद्गुणान् सङ्गृहीति।"),
        "dua_ihdini_saddidni" to DuaText("मा मार्गनिर्देशं कृत्वा मां सम्यक् कुरु।", "हे अल्लाहः, मां मार्गनिर्देशं कृत्वा सम्यक् मार्गम् अवलम्बय।", "सः पैगम्बरः अली (र) इत्यस्मै इदं उपदिशत्।", "मार्गस्य मार्गनिर्देशं, सादद् इत्यस्य बाणस्य सरलता इति चिन्तयतु।"),
        "dua_hubbaka" to DuaText("अल्लाहस्य प्रेमाय प्रार्थय।", "हे अल्लाहः, अहं तव प्रेम, ये युष्मभ्यन्तं प्रेम कुर्वन्ति तेषां प्रेम, ये मह्यं युष्मभ्यन्तं प्रावर्तयन्ति तेषाम् प्रेम च प्रार्थये। हे अल्लाहः, मम, मम कुटुम्बस्य, शीतलजलस्य च अपेक्षया तव प्रेम मह्यं प्रियं कुरु।", "दावूद् (अ. स.) इत्यस्य दुआ, पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् इत्यनेन सम्बद्धम्।", "अल्लाहस्य प्रेम एव बृहत्तमं धनम्।"),
        "dua_filal_khayrat" to DuaText("सत्कर्मं च दुष्टं च वदतु।", "हे अल्लाहः, अहं युष्मभ्यम् प्रार्थयेम यत्, सत्क्रियासु कर्तुम्, दुष्टकर्माणि परित्यज्य दरिद्रान् प्रेमुम्, तथा च त्वं माम् क्षमस्व, मम प्रति करुणामहम् इति। तथा च यदा भवान् कस्यापि जनानाम् कृते परीक्षणं इच्छति तर्हि मां विना परीक्षां स्वीकरोतु। अहं युष्मभ्यम् प्रार्थयेते, युष्मभ्यम् प्रेमकर्तृणां प्रेम, युष्मभ्यम् समीपीकृत्यु च कर्माणां प्रेम।", "अल्लाहः स्वप्नाते पैगम्बरं एतां दुआं उपदिशत्।", "सः पैगम्बरः (सः) अवदत् यत् सत्यमेव, अतः शिक्षयतु, शिक्षयतु च।"),
        "dua_bi_ilmikal_ghayb" to DuaText("जीवनं यावत् उत्तमं भवति तावत् मह्यं जीवितुं वदतु।", "हे अल्लाहः, अदृश्यस्य विषये भवतः ज्ञानेन, सृष्टेः उपरि भवतः शक्त्या च, यावत् त्वं जानासि यत् जीवनं मम कृते उत्तमम् अस्ति, तथा च मह्यं स्वीकरोतु यदा त्वं जानासि यत् मृत्युः मम कृते उत्तमः इति। हे अल्लाहः, अहं युष्मभ्यम् अकृत्य सार्वजनिकरूपेण च भयम् प्रार्थयेते, सन्तुष्टौ क्रोधौ सत्यवाक्यं, दारिद्र्ये धनसम्पदे च मितत्वं च।", "अम्मर् इब्न् यासिर (र) इत्यस्य प्रार्थना दुआ (उद्घाटनभागः)।", "पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् इत्यनेन प्रार्थनायां एतत् दुआ कृतम्।"),
        "dua_ism_azam_mannan" to DuaText("इस्मे-ए-आज़मः अल्-मन्नान्", "हे अल्लाहः, अहं युष्मभ्यम् प्रार्थयेते, यतो हि सर्व प्रशंसा युष्म एव अस्ति, युष्मपि विना अन्यः ईश्वरः नास्ति, यः अनुग्रहं प्रददाति, आकाशाणां पृथिव्या च निर्मातृः। हे महिमायाः सम्मानस्य च स्वामी, हे नित्यजीवा!", "सः सः अल्लाहस्य महानम्ना दुवा इति निर्मितवान् इति पैगम्बरः (सः) अवदत्।", "अस्य नाम्ना निर्मितस्य दुआ इत्यस्य उत्तरम् अस्ति।"),
        "dua_ism_azam_ahad_samad" to DuaText("इस्मे-ए-आज़मः अल्-अहद् अस्-समद्", "हे अल्लाह, अहं युष्मभ्यम् प्रार्थयेम, यतः युष्महि अल्लाह इति साक्ष्यं ददामि, युष्मपि विना अन्यः देवः नास्ति, सः एव एकमात्रः, स्वावलम्बी, यः न जन्म करोति, न जन्म करोति, न च तस्य किमपि तुल्यं नास्ति।", "सः सः सः सः महान् नाम अल्लाहः इति प्रार्थयत् इति सः पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् अवदत्।", "तेन पृष्टा सः ददति, यदा आहूयते तदा सः उत्तरयति।"),
        "dua_thabbitni_hadiyan" to DuaText("मह्यं दृढं, मार्गदर्शितं, मार्गदर्शकं च कुरु।", "हे अल्लाहः, मां दृढं कुरु, तथा च मार्गदर्शिः मार्गदर्शि च करोतु।", "पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् इत्येषः जारीर् (रा) इत्यस्य कृते एतत् दुआ (स्वयं'थाबित्नी'इति वदति) कृतवान्।", "जरीर् (आर्. ए.) इत्यस्य मूल-दुआ इत्यस्मिन्'थाबित्-हु'इति शब्दस्य उपयोगः भवति।"),
        "dua_rabbighfir_tub_alayya" to DuaText("मम पश्चात्तापम् स्वीकरोतु च।", "हे मम प्रभुः, मां क्षमाय मम पश्चात्तापम् स्वीकरोतु। त्वं पश्चात्तापस्य साधकः, दयावानः।", "एकस्यां सभायां शतवारं-पैगम्बरस्य अभ्यासः।", "सहचरैः, एकवासे शतवारं सः पैगम्बरः उक्तवान् इति गणितम्।"),
        "dua_rafiq_ala" to DuaText("मृतस्य व्यक्तेः दुआ", "हे अल्लाहः, मा क्षमां करोतु, मम प्रति करुणां करोतु, सर्वोच्चसहचरेन सह सह मम सहवर्ततु।", "पैगम्बरस्य अन्तिमः दुआ-रोगिणां स्वार्थं वक्तुं।", "सः पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् इत्येषः स्वस्य निधनसमये एतत् दुआ कृतवान्।"),
        "dua_la_bas_tahur" to DuaText("रोगिणां आश्वस्तिः शुध्दीकरणं", "हानिः नास्ति; यदि अल्लाहः इच्छति तर्हि तत् (पापात्) शुद्दीकरणं भवति।", "यदा रोगिनः आगच्छन्ति तदा आश्वस्तिम्।", "सः पैगम्बरः (सः) रोगिणां सन्दर्शने इदं उक्तवान्।"),
        "dua_talqeen" to DuaText("तालकीन्-मरणाय", "अल्लाहस्य अतिरिक्तं पूजनीयः अधिकारः अन्यत् नास्ति।", "मृतस्य व्यक्तेः समीपे कलिमा पठतु (तान् उक्तुं न बलात्)।", "यः अन्तिमशब्दं'ला इलाहा इल्लल्लाह'इति भवति सः स्वर्गं प्रविशति (अबू दावूद् 3116)।"),
        "dua_ahyini_ma_kanat" to DuaText("मृत्यु-इच्छायाः स्थाने", "हे अल्लाहः, यावत् मम जीवनं उत्तमं भवति तावत् कालं मां जीवतु, मृत्युः मम कृते उत्तमः भवति तदा मां च स्वीकरोतु।", "कष्टे मृत्युं इच्छमाणम्।", "सः पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् इत्ययम् मृत्योः इच्छां वर्जितवान्, तस्य स्थाने इदं शिक्षयत्।"),
        "dua_for_one_i_cursed" to DuaText("कस्यापि कृते अहं शब्दैः व्रणामि।", "हे अल्लाहः, यः विश्वासी अहं अपमानितवान्, सः पुनरुत्थानदिने तस्य कृते भवतः समीपस्थः साधनं कल्पयतु।", "यस्य कृते भवान् क्रोधेन दुष्टं भाषत।", "पैगम्बरस्य दूतः।"),
    )
}
